@log_input_and_output
def start_lte_downlink_test(connection, distname_realtime, test_model, earfcn, phy_cell_id=None,
                            tdd_spec_subf_conf=7, tdd_frame_conf=1, timeout=60):
    """
    Starts LTE Downlink Test Model.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param distname_realtime: realtime dist_name object of particular cell,
                              e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-3344/LNCEL_R-1"
    :type distname_realtime: str
    :param test_model: type of downlink test model, one of the following: "E-TM1.1", "E-TM1.2", "E-TM1.3",
                       "E-TM2", "E-TM2a", "E-TM3.1a", "E-TM3.1", "E-TM3.2", "E-TM3.3", "MIMO-TM3.1", "E-TM1.1_EE_LOW",
                       "E-TM1.1_EE_MID", "E-TM1.1_EE_HIGH", "ChirpUp", "ChirpDown"
    :type test_model: str
    :param earfcn: downlink earfcn of particular cell
    :type earfcn: int
    :param phy_cell_id: physical cell ID of particular cell
    :type phy_cell_id: int
    :param tdd_spec_subf_conf: parameter required to start test model, default set on 7
    :type tdd_spec_subf_conf: int
    :param tdd_frame_conf: parameter required to start test model, default set on 1
    :type tdd_frame_conf: int
    :param timeout: timeout value in seconds for the start test model operation, default is 60 seconds.
    :type timeout: int or str
    :return: dict of formatted test result and result message
             e.g. {"status": "Succeeded", "msg": "Test model has started successfully"}
    :rtype: dict
    """
    try:
        adm = admin()
        start_test_response = adm.start_downlink_test(dist_name=distname_realtime,
                                                      test_model=test_model,
                                                      earfcn=earfcn,
                                                      phy_cell_id=phy_cell_id,
                                                      tdd_spec_sub_conf=tdd_spec_subf_conf,
                                                      tdd_frame_conf=tdd_frame_conf,
                                                      timeout=int(timeout),
                                                      connection=connection)

        log_operation("Downlink test model has successfully been started.")
        return {"status": "Succeeded",
                "msg": start_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("Downlink test model start failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


