@log_input_and_output
def start_lte_pusch_performance_test(connection, distname_realtime, earfcn, pusch_format=1,
                                     nb_subframe_offset=None, nb_repetitions=None, nb_subcarrier_index=None,
                                     reporting_time_interval=1, tdd_spec_subf_conf=None, tdd_frame_conf=None,
                                     timeout=60,
                                     reference_channel_number=None, reference_channel_number_nb_linked=None,
                                     local_cell_res_id_nb_linked=None,
                                     inband_prb_index_ul=None, guardband_index_ul=None,
                                     resource_block_offset=0, digital_output_type="SerialRs",
                                     enable_harq=None, enable_digital_output=True, measured_frc=None,
                                     reception_subframe=0, exception_subframe=0,
                                     reception_bundle=1, expection_bundle=0):
    """
    Starts LTE PUSCH Performance Test Model.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param distname_realtime: realtime dist_name object of particular cell to start performance test,
                              e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-3344/LNCEL_R-1"
                              In case of test on linked NB IoT cell, distname of host cell should be set, id of linked
                              IoT cell must be defined as local_cell_res_id_nb_linked parameter.
    :type distname_realtime: str
    :param earfcn: uplink earfcn of particular cell
    :type earfcn: int
    :param pusch_format: format of pusch performance test, possible values: 1 or 2, defaults to 1.
    :type pusch_format: str or int
    :param nb_subframe_offset: narrowband IoT subframe offset, range <0 to 255>, defaults to None
    :type nb_subframe_offset: int or None
    :param nb_repetitions: parameter required to start test model on narrowband IoT cell. One of the following:
                           “NBR_1”, “NBR_2”, “NBR_16”, “NBR_64” or None, defaults to None
    :type nb_repetitions: str or None
    :param nb_subcarrier_index: narrowband IoT sybcarrier index, range <0 to 47>, defaults to None
    :type nb_subcarrier_index: int or str or None
    :param reporting_time_interval: reporting time interval (in seconds), default set on 1
    :type reporting_time_interval: int or str
    :param tdd_spec_subf_conf: parameter required to start test model, defaults to 7
    :type tdd_spec_subf_conf: int
    :param tdd_frame_conf: parameter required to start test model, defaults to 1
    :type tdd_frame_conf: int
    :param timeout: timeout value in seconds for the start test model operation, default is 60 seconds.
    :type timeout: int or str

    PARAMETERS FOR PUSCH FORMAT 1:
    :param reference_channel_number: type of uplink test model required only for format 1, one of the following:
                       "A3_1", "A3_2", "A3_3", "A3_4", "A3_5", "A3_6", "A3_7", "A4_1", "A4_2", "A4_3", "A4_4", "A4_5",
                       "A4_6", "A4_7", "A4_8", "A5_1", "A5_2", "A5_3", "A5_4", "A5_5", "A5_6", "A5_7", "A7_1", "A7_2",
                       "A7_3", "A7_4", "A7_5", "A7_6", "A8_1", "A8_2", "A8_3", "A8_4", "A8_5", "A8_6" or None in case
                       of pusch_format 2. Defaults to None
    :type reference_channel_number: str or None
    :param reference_channel_number_nb_linked: type of uplink test model for NB IoT cells, Defaults to None
    :type reference_channel_number_nb_linked: str or None
    :param local_cell_res_id_nb_linked: configuration id of linked NB IoT cell, defaults to None
    :type local_cell_res_id_nb_linked: int or None
    :param inband_prb_index_ul: narrowband IoT inband prb index for ul channel, range <0 to 99>, defaults to None
    :type inband_prb_index_ul: int or string or None
    :param guardband_index_ul: narrowband IoT guardband index for ul channel, One of following: “undefined”,
                              “plus4590kHz”, “plus6840kHz”, “plus9090kHz”, “minus4590kHz”, “minus6840kHz”,
                              “minus9090kHz” or None, defaults to None
    :type guardband_index_ul: str or None
    :param resource_block_offset: parameter required to start test model, default set on 0
    :type resource_block_offset:  int
    :param digital_output_type: type of digital output, One of the following: "BinaryHarq", "SerialAgilent",
                                "SerialRs", defaults to "SerialRs".
    :type digital_output_type: str
    :param enable_harq: harq enabling, True or False, defaults to True
    :type enable_harq: bool
    :param enable_digital_output: digital output enabling, True or False, defaults to True.
    :type enable_digital_output: bool
    :param measured_frc: parameter required to start test model, one of the following: “nbLinked”, “both”, “1Dot92Mbps”,
                         or None, defaults None
    :type measured_frc: str on None

    PARAMETERS FOR PUSCH FORMAT 2:
    :param reception_subframe: parameter required to start test model, range <0 to 1023>, defaults to 0
    :type reception_subframe: int
    :param exception_subframe: parameter required to start test model, range <0 to 1023>, defaults to 0
    :type exception_subframe: int
    :param reception_bundle: parameter required to start test model, range <1 to 31>, defaults to 1
    :type reception_bundle: int
    :param expection_bundle: parameter required to start test model, range <1 to 31>, defaults to 0
    :type expection_bundle: int

    :return: dict of formatted test result and result message
             e.g. {"status": "Succeeded", "msg": "Test model has started successfully"}
    :rtype: dict
    :raises IncorrectTestModelParameter: when incorrect provided pusch_format parameter value  or some required
                                         parameter not set for particular pusch format
    """
    if int(pusch_format) == 1 and reference_channel_number is None:
        raise IncorrectTestModelParameter("Parameter 'reference_channel_number' should be set "
                                          "in case of PUSCH format 1")

    if int(pusch_format) == 2 and nb_subcarrier_index is None:
        raise IncorrectTestModelParameter("Parameter 'nb_subcarrier_index' should be set "
                                          "in case of PUSCH format 2")

    try:
        adm = admin()
        if int(pusch_format) == 1:
            start_test_response = adm.start_uplink_test(
                dist_name=distname_realtime,
                earfcn=earfcn,
                reference_channel_number=reference_channel_number.replace('-', '_').replace('.', '_'),
                reference_channel_number_nb_linked=reference_channel_number_nb_linked,
                reporting_time_interval=int(reporting_time_interval),
                resource_block_offset=resource_block_offset,
                digital_output_type=digital_output_type,
                enable_harq=enable_harq,
                enable_digital_output=enable_digital_output,
                tdd_frame_conf=tdd_frame_conf,
                tdd_spec_subf_conf=tdd_spec_subf_conf,
                nb_subcarrier_index=nb_subcarrier_index,
                measured_frc=measured_frc,
                local_cell_res_id_nb_linked=local_cell_res_id_nb_linked,
                inband_prb_index_ul=inband_prb_index_ul,
                guardband_index_ul=guardband_index_ul,
                nb_repetitions=nb_repetitions,
                nb_subframe_offset=int(nb_subframe_offset) if nb_subframe_offset is not None else nb_subframe_offset,
                timeout=int(timeout),
                connection=connection)
        elif int(pusch_format) == 2:
            start_test_response = adm.start_lte_uplink_ccm_n_pusch_format_2_test(
                lncel_rdn=distname_realtime,
                earfcn=earfcn,
                reporting_time_interval=int(reporting_time_interval),
                reception_subframe=int(reception_subframe) if reception_subframe is not None else reception_subframe,
                exception_subframe=int(exception_subframe) if exception_subframe is not None else exception_subframe,
                nb_subcarrier_index=nb_subcarrier_index,
                nb_repetitions=nb_repetitions,
                nb_subframe_offset=int(nb_subframe_offset) if nb_subframe_offset is not None else nb_subframe_offset,
                expection_bundle=int(expection_bundle) if expection_bundle is not None else expection_bundle,
                reception_bundle=int(reception_bundle) if reception_bundle is not None else reception_bundle,
                tdd_frame_conf=tdd_frame_conf,
                tdd_spec_subf_conf=tdd_spec_subf_conf,
                timeout=int(timeout),
                connection=connection)
        else:
            raise IncorrectTestModelParameter("Parameter 'pusch_format' should be equal 1 or 2")

        log_operation(f"PUSCH format {pusch_format} performance test has successfully been started.")
        return {"status": "Succeeded",
                "msg": start_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result(f"PUSCH format {pusch_format} performance test start failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


@log_input_and_output
def stop_lte_pusch_performance_test(connection, distname_realtime, pusch_format=1, timeout=10):
    """
    Stops LTE PUSCH Performance Test Model.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param distname_realtime: realtime dist_name object of particular cell,
                              e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-3344/LNCEL_R-1"
    :type distname_realtime: str
    :param pusch_format: format of pusch performance test, possible values: 1 or 2, defaults to 1.
    :type pusch_format: str or int
    :param timeout: timeout value in seconds for the stop test model operation, default is 10 seconds.
    :type timeout: int or str
    :return: dict of formatted test result and result message,
             e.g. {"status": "Succeeded", "msg": "Test model has stopped successfully"}
    :rtype: dict
    :raises IncorrectTestModelParameter: when incorrect provided pusch_format parameter value
    """
    try:
        adm = admin()
        if int(pusch_format) == 1:
            stop_test_response = adm.stop_uplink_test(dist_name=distname_realtime,
                                                      timeout=int(timeout),
                                                      connection=connection)
        elif int(pusch_format) == 2:
            stop_test_response = adm.stop_lte_uplink_ccm_test(lncel_rdn=distname_realtime,
                                                              timeout=int(timeout),
                                                              connection=connection)
        else:
            raise IncorrectTestModelParameter("Parameter 'pusch_format' should be equal 1 or 2")

        log_operation("PUSCH performance test has successfully been stopped.")
        return {"status": "Succeeded",
                "msg": stop_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("PUSCH performance test stop failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


@log_input_and_output
def start_lte_prach_performance_test(connection, distname_realtime, earfcn, reporting_time_interval=1,
                                     tdd_spec_subf_conf=None, tdd_frame_conf=None, subcarrier_offset=None,
                                     num_subcarriers=None, nb_repetitions=None, nb_subframe_offset=None, config_index=0,
                                     preamble_index=7, accepted_timing_error=10000, constant_offset=10000,
                                     reception_subframe=0, exception_subframe=0, reception_bundle=1, expection_bundle=0,
                                     timeout=60):
    """
    Starts LTE PRACH Performance Test Model.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param distname_realtime: realtime dist_name object of particular cell to start performance test,
                              e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-3344/LNCEL_R-1"
    :type distname_realtime: str
    :param earfcn: uplink earfcn of particular cell
    :type earfcn: int
    :param reporting_time_interval: reporting time interval (in seconds), defaults to 1
    :type reporting_time_interval: int or str
    :param tdd_spec_subf_conf: parameter required to start test model, defaults to 7
    :type tdd_spec_subf_conf: int
    :param tdd_frame_conf: parameter required to start test model, defaults to 1
    :type tdd_frame_conf: int
    :param subcarrier_offset: parameter required to start test model, defaults to 1
    :type subcarrier_offset: int
    :param num_subcarriers: parameter required to start test model, defaults to 1
    :type num_subcarriers: int
    :param nb_repetitions: parameter required to start test model on narrowband IoT cell. One of the following:
                           'NBR_8', 'NBR_32' or None, defaults to None
    :type nb_repetitions: str or None
    :param nb_subframe_offset: narrowband IoT subframe offset, range <0 to 255>, defaults to None
    :type nb_subframe_offset: int or None
    :param config_index: parameter required to start test model, range <0 to 2>, defaults to 0
    :type config_index: int
    :param preamble_index: parameter required to start test model, range <0 to 47>, defaults to 7
    :type preamble_index: int
    :param accepted_timing_error: parameter required to start test model, range <0 to 65535>, defaults to 10000
    :type accepted_timing_error: int
    :param constant_offset: parameter required to start test model, range <0 to 65535>, defaults to 10000
    :type constant_offset: int
    :param reception_subframe: parameter required to start test model, range <0 to 1023>, defaults to 0
    :type reception_subframe: int
    :param exception_subframe: parameter required to start test model, range <0 to 1023>, defaults to 0
    :type exception_subframe: int
    :param reception_bundle: parameter required to start test model, range <1 to 31>, defaults to 1
    :type reception_bundle: int
    :param expection_bundle: parameter required to start test model, range <1 to 31>, defaults to 0
    :type expection_bundle: int
    :param timeout: timeout value in seconds for the start test model operation, default is 60 seconds.
    :type timeout: int or str
    :return: dict of formatted test result and result message
             e.g. {"status": "Succeeded", "msg": "Test model has started successfully"}
    :rtype: dict
    """
    try:
        adm = admin()
        start_test_response = adm.start_lte_uplink_ccm_n_prach_test(
            lncel_rdn=distname_realtime,
            earfcn=earfcn,
            reporting_time_interval=int(reporting_time_interval),
            reception_subframe=int(reception_subframe) if reception_subframe is not None else reception_subframe,
            exception_subframe=int(exception_subframe) if exception_subframe is not None else exception_subframe,
            subcarrier_offset=subcarrier_offset,
            num_subcarriers=num_subcarriers,
            nb_repetitions=nb_repetitions,
            nb_subframe_offset=int(nb_subframe_offset) if nb_subframe_offset is not None else nb_subframe_offset,
            config_index=int(config_index) if config_index is not None else config_index,
            preamble_index=int(preamble_index) if preamble_index is not None else preamble_index,
            accepted_timing_error=int(accepted_timing_error) if accepted_timing_error is not None
            else accepted_timing_error,
            constant_offset=int(constant_offset) if constant_offset is not None else constant_offset,
            expection_bundle=int(expection_bundle) if expection_bundle is not None else expection_bundle,
            reception_bundle=int(reception_bundle) if reception_bundle is not None else reception_bundle,
            tdd_frame_conf=tdd_frame_conf,
            tdd_spec_subf_conf=tdd_spec_subf_conf,
            timeout=int(timeout),
            connection=connection)

        log_operation("PRACH performance test has successfully been started.")
        return {"status": "Succeeded",
                "msg": start_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("PRACH performance test start failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


